-- 0102_template_product_pages.sql (storefront templates, 2026-10-23)
--
-- Adds each template's product page (kind = 'product', slug 'product') to the
-- database copy, generated from the code templates by
-- `pnpm --filter @workspace/store-sections template:product-page-sql ../db/migrations/0102_template_product_pages.sql`.
-- Per template, in one transaction:
--   1. an admin draft (draft_config) without a product page gets it appended;
--   2. the current version gets a new version (max + 1, "product page") with
--      the page appended, and becomes current;
--   3. meta.pageNames.product is filled when missing.
-- Templates that exist in code but not in the database (or are soft-deleted)
-- match no row and are skipped. Every block is guarded by "no product page
-- yet", so it is idempotent. Stores' drafts and live sites are not touched.
--
-- Rollback (per template): make the previous version current again, then
-- delete the version whose changelog is 'product page'.

BEGIN;

-- tallaby-classic
-- Lock the template row (as publishTemplateVersion does) before max(version) + 1.
SELECT 1 FROM templates WHERE key = 'tallaby-classic' AND deleted_at IS NULL FOR UPDATE;

-- Draft: the page is appended to an admin draft that has none.
UPDATE templates t
SET draft_config = jsonb_set(t.draft_config, '{pages}', (t.draft_config->'pages') || '{"kind":"product","slug":"product","isHome":false,"name":"صفحة المنتج","showInNav":false,"seo":{},"content":{"sections":[{"id":"tallaby-product-main","sectionId":"custom-section","version":1,"props":{},"componentTree":[{"id":"tallaby-product-main-n1","type":"section","props":{"label":"المنتج","translations":{"en":{"label":"Product"}}},"children":[{"id":"tallaby-product-main-n2","type":"container","props":{"label":"الحاوية","translations":{"en":{"label":"Container"}}},"children":[{"id":"tallaby-product-main-n3","type":"textLink","props":{"label":"رابط الرجوع","text":"رجوع للمتجر","href":"/","translations":{"en":{"label":"Back link","text":"Back to the store"}}},"children":[],"style":{"fontSize":"sm","fontWeight":"bold","color":"primary","marginBottom":20},"breakpointStyles":{"mobile":{"marginBottom":14}}},{"id":"tallaby-product-main-n4","type":"grid","props":{"label":"المعرض والشراء","translations":{"en":{"label":"Gallery and buy column"}}},"children":[{"id":"tallaby-product-main-n5","type":"productGallery","props":{"zoom":true,"label":"صور المنتج","thumbs":"bottom","translations":{"en":{"label":"Product gallery"}}},"children":[],"style":{"colSpan":7,"position":"sticky","insetTop":"96px"},"breakpointStyles":{"tablet":{"colSpan":1,"position":"relative","insetTop":"0px"}}},{"id":"tallaby-product-main-n6","type":"vFlex","props":{"label":"عمود الشراء","translations":{"en":{"label":"Buy column"}}},"children":[{"id":"tallaby-product-main-n7","type":"productSeller","props":{"label":"البائع","translations":{"en":{"label":"Seller"}}},"children":[]},{"id":"tallaby-product-main-n8","type":"productStock","props":{"label":"المخزون","translations":{"en":{"label":"Stock"}}},"children":[]},{"id":"tallaby-product-main-n9","type":"heading","props":{"role":"title","bind":"title","label":"اسم المنتج","text":"اسم المنتج","level":"h1","translations":{"en":{"label":"Product name","text":"Product name"}}},