2","translations":{"en":{"text":"What buyers say"}}},"children":[],"style":{"fontSize":"display-sm","fontWeight":"extrabold","lineHeight":"tight"}}],"style":{"gap":6}}],"style":{"justifyContent":"between","alignItems":"end","gap":16,"marginBottom":24}},{"id":"tallaby-product-reviews-n10","type":"productReviews","props":{"label":"التقييمات والأسئلة","translations":{"en":{"label":"Reviews and questions"}}},"children":[]}],"style":{"gap":8}}],"style":{"maxWidth":"960px"}}],"style":{"paddingTop":64,"paddingBottom":64,"background":"white","marginTop":72},"breakpointStyles":{"mobile":{"paddingTop":44,"paddingBottom":44,"marginTop":48}}}],"source":"tallaby-product-reviews@1"},{"id":"tallaby-product-related","sectionId":"custom-section","version":1,"props":{},"componentTree":[{"id":"tallaby-product-related-n1","type":"section","props":{"label":"منتجات مشابهة","translations":{"en":{"label":"Related products"}}},"children":[{"id":"tallaby-product-related-n2","type":"container","props":{"label":"الحاوية","translations":{"en":{"label":"Container"}}},"children":[{"id":"tallaby-product-related-n3","type":"hFlex","props":{"label":"رأس القسم","translations":{"en":{"label":"Section head"}}},"children":[{"id":"tallaby-product-related-n4","type":"vFlex","props":{"role":"intro","label":"العنوان","translations":{"en":{"label":"Heading"}}},"children":[{"id":"tallaby-product-related-n5","type":"hFlex","props":{"label":"العنوان الصغير","translations":{"en":{"label":"Eyebrow"}}},"children":[{"id":"tallaby-product-related-n6","type":"div","props":{"label":"نقطة","translations":{"en":{"label":"Dot"}}},"children":[],"style":{"background":"accent","width":"8px","minHeight":8,"radius":999}},{"id":"tallaby-product-related-n7","type":"text","props":{"role":"eyebrow","text":"من نفس القسم","translations":{"en":{"text":"From the same aisle"}}},"children":[],"style":{"fontSize":"xs","fontWeight":"bold","letterSpacing":"wide","textTransform":"uppercase","color":"primary"}}],"style":{"gap":8,"alignItems