    'product page'
  FROM cur
  WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(cur.config->'pages') p WHERE p->>'kind' = 'product')
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(cur.config->'pages') p WHERE p->>'slug' = 'product')
  RETURNING id, template_id
)
UPDATE templates t SET current_version_id = nv.id, updated_at = now()
FROM new_version nv
WHERE t.id = nv.template_id;

-- Meta: the page's gallery name, never overwriting an existing value.
UPDATE templates t
SET meta = jsonb_set(t.meta, '{pageNames}', COALESCE(t.meta->'pageNames', '{}'::jsonb) || jsonb_build_object('product', '{"ar":"صفحة المنتج","en":"Product page"}'::jsonb))
WHERE t.key = 'arcade' AND t.deleted_at IS NULL
  AND t.meta->'pageNames'->'product' IS NULL;

-- arena
-- Lock the template row (as publishTemplateVersion does) before max(version) + 1.
SELECT 1 FROM templates WHERE key = 'arena' AND deleted_at IS NULL FOR UPDATE;

-- Draft: the page is appended to an admin draft that has none.
UPDATE templates t
SET draft_config = jsonb_set(t.draft_config, '{pages}', (t.draft_config->'pages') || '{"kind":"product","slug":"product","isHome":false,"name":"صفحة المنتج","showInNav":false,"seo":{},"content":{"sections":[{"id":"arena-product-main","sectionId":"custom-section","version":1,"props":{},"componentTree":[{"id":"arena-product-main-n1","type":"section","props":{"label":"المنتج","translations":{"en":{"label":"Product"}}},"children":[{"id":"arena-product-main-n2","type":"container","props":{"label":"الحاوية","translations":{"en":{"label":"Container"}}},"children":[{"id":"arena-product-main-n3","type":"textLink","props":{"label":"رابط الرجوع","text":"رجوع للمتجر","href":"/","translations":{"en":{"label":"Back link","text":"Back to the store"}}},"children":[],"style":{"fontSize":"sm","color":"muted","marginBottom":20},"breakpointStyles":{"mobile":{"marginBottom":14}}},{"id":"arena-product-main-n4","type":"grid","props":{"label":"المعرض والشراء","translations":{"en":{"label":"Gallery and buy column"}}},"children":[{"id":"arena-product-main-n5","type":"productGallery","props":{"zoom":true,"label":"صور المنتج","thumbs":"bottom","translations":{"en":{"label":"Product gallery"}}},"children":[],"style":{"colSpan":7,"position":"sticky","insetTop":"96px"},"breakpointStyles":{"tablet":{"colSpan":1,"position":"relative","insetTop":"0px"}}},{"id":"arena-product-main-n6","type":"vFlex","props":{"label":"عمود الشراء","translations":{"en":{"label":"Buy column"}}},"children":[{"id":"arena-product-main-n7","type":"productSeller","props":{"label":"البائع","translations":{"en":{"label":"Seller"}}},"children":[]},{"id":"arena-product-main-n8","type":"productStock","props":{"label":"المخزون","translations":{"en":{"label":"Stock"}}},"children":[]},{"id":"arena-product-main-n9","type":"heading","props":{"role":"title","bind":"title","label":"اسم المنتج","text":"اسم المنتج","level":"h1","translations":{"en":{"label":"Product name","text":"Product name"}}},"children":[],"style":{"fontSize":"3xl","f