n":{"label":"Product name"}}},"children":[{"id":"botanica-product-related-n18","type":"text","props":{"bind":"title","text":"اسم المنتج","translations":{"en":{"text":"Product name"}}},"children":[],"style":{"fontWeight":"semibold","lineHeight":"snug"}}],"style":{"paddingTop":0,"paddingBottom":0,"paddingStart":0,"paddingEnd":0,"color":"foreground"}},{"id":"botanica-product-related-n19","type":"hFlex","props":{"label":"السعر","translations":{"en":{"label":"Price"}}},"children":[{"id":"botanica-product-related-n20","type":"text","props":{"bind":"price","text":"٢٥٠ ج.م","translations":{"en":{"text":"EGP 250"}}},"children":[],"style":{"fontWeight":"bold","color":"primary","fontSize":"md"}},{"id":"botanica-product-related-n21","type":"text","props":{"bind":"compareAtPrice","text":"٣٠٠ ج.م","translations":{"en":{"text":"EGP 300"}}},"children":[],"style":{"color":"muted","fontSize":"sm","italic":true}}],"style":{"gap":8,"alignItems":"center"}}],"style":{"gap":6}},{"id":"botanica-product-related-n22","type":"addToCart","props":{"label":"أضف للسلة","translations":{"en":{"label":"Add to cart"}}},"children":[]}],"style":{"gap":10}}],"style":{"columns":4,"gap":24},"breakpointStyles":{"tablet":{"columns":3},"mobile":{"columns":2,"gap":14}}}]}],"style":{"paddingTop":48,"paddingBottom":64},"breakpointStyles":{"mobile":{"paddingTop":32,"paddingBottom":48}}}],"source":"botanica-product-related@1"}]}}'::jsonb),
    'product page'
  FROM cur
  WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(cur.config->'pages') p WHERE p->>'kind' = 'product')
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(cur.config->'pages') p WHERE p->>'slug' = 'product')
  RETURNING id, template_id
)
UPDATE templates t SET current_version_id = nv.id, updated_at = now()
FROM new_version nv
WHERE t.id = nv.template_id;

-- Meta: the page's gallery name, never overwriting an existing value.
UPDATE templates t
SET meta = jsonb_set(t.meta, '{pageNames}', COALESCE(t.meta->'pageNames', '{}'::jsonb) || jsonb_build_object('product', '{"ar":"صفحة المنتج","en":"Product page"}'::jsonb))
WHERE t.key = 'botanica' AND t.deleted_at IS NULL
  AND t.meta->'pageNames'->'product' IS NULL;

-- nest
-- Lock the template row (as publishTemplateVersion does) before max(version) + 1.
SELECT 1 FROM templates WHERE key = 'nest' AND deleted_at IS NULL FOR UPDATE;

