SET draft_config = jsonb_set(t.draft_config, '{pages}', (t.draft_config->'pages') || '{"kind":"product","slug":"product","isHome":false,"name":"صفحة المنتج","showInNav":false,"seo":{},"content":{"sections":[{"id":"lego-product-main","sectionId":"custom-section","version":1,"props":{},"componentTree":[{"id":"lego-product-main-n1","type":"section","props":{"label":"المنتج","translations":{"en":{"label":"Product"}}},"children":[{"id":"lego-product-main-n2","type":"container","props":{"label":"الحاوية","translations":{"en":{"label":"Container"}}},"children":[{"id":"lego-product-main-n3","type":"textLink","props":{"label":"رابط الرجوع","text":"رجوع للألعاب","href":"/","translations":{"en":{"label":"Back link","text":"Back to the toys"}}},"children":[],"style":{"fontSize":"sm","color":"muted","marginBottom":20},"breakpointStyles":{"mobile":{"marginBottom":14}}},{"id":"lego-product-main-n4","type":"grid","props":{"label":"المعرض والشراء","translations":{"en":{"label":"Gallery and buy column"}}},"children":[{"id":"lego-product-main-n5","type":"productGallery","props":{"zoom":true,"label":"صور المنتج","thumbs":"bottom","translations":{"en":{"label":"Product gallery"}}},"children":[],"style":{"colSpan":7,"position":"sticky","insetTop":"96px"},"breakpointStyles":{"tablet":{"colSpan":1,"position":"relative","insetTop":"0px"}}},{"id":"lego-product-main-n6","type":"vFlex","props":{"label":"عمود الشراء","translations":{"en":{"label":"Buy column"}}},"children":[{"id":"lego-product-main-n7","type":"productSeller","props":{"label":"البائع","translations":{"en":{"label":"Seller"}}},"children":[]},{"id":"lego-product-main-n8","type":"productStock","props":{"label":"المخزون","translations":{"en":{"label":"Stock"}}},"children":[]},{"id":"lego-product-main-n9","type":"heading","props":{"role":"title","bind":"title","label":"اسم المنتج","text":"اسم المنتج","level":"h1","translations":{"en":{"label":"Product name","text":"Product name"}}},"children":[],"style":{"fontSize":"3xl","fontWeight"