":"madrasa-product-related-n18","type":"text","props":{"bind":"title","text":"اسم المنتج","translations":{"en":{"text":"Product name"}}},"children":[],"style":{"fontWeight":"semibold","lineHeight":"snug"}}],"style":{"paddingTop":0,"paddingBottom":0,"paddingStart":0,"paddingEnd":0,"color":"foreground"}},{"id":"madrasa-product-related-n19","type":"hFlex","props":{"label":"السعر","translations":{"en":{"label":"Price"}}},"children":[{"id":"madrasa-product-related-n20","type":"text","props":{"bind":"price","text":"٢٥٠ ج.م","translations":{"en":{"text":"EGP 250"}}},"children":[],"style":{"fontWeight":"bold","color":"primary","fontSize":"md"}},{"id":"madrasa-product-related-n21","type":"text","props":{"bind":"compareAtPrice","text":"٣٠٠ ج.م","translations":{"en":{"text":"EGP 300"}}},"children":[],"style":{"color":"muted","fontSize":"sm","italic":true}}],"style":{"gap":8,"alignItems":"center"}}],"style":{"gap":6}},{"id":"madrasa-product-related-n22","type":"addToCart","props":{"label":"أضف للسلة","translations":{"en":{"label":"Add to cart"}}},"children":[]}],"style":{"gap":10}}],"style":{"columns":4,"gap":24},"breakpointStyles":{"tablet":{"columns":3},"mobile":{"columns":2,"gap":14}}}]}],"style":{"paddingTop":48,"paddingBottom":64},"breakpointStyles":{"mobile":{"paddingTop":32,"paddingBottom":48}}}],"source":"madrasa-product-related@1"}]}}'::jsonb),
    draft_version = t.draft_version + 1,
    draft_updated_at = now()
WHERE t.key = 'madrasa' AND t.deleted_at IS NULL
  AND t.draft_config IS NOT NULL AND jsonb_typeof(t.draft_config->'pages') = 'array'
  AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(t.draft_config->'pages') p WHERE p->>'kind' = 'product')
  AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(t.draft_config->'pages') p WHERE p->>'slug' = 'product');

-- Version: current config + the page, as version max + 1, made current.
WITH cur AS (
  SELECT t.id AS template_id, v.config, v.schema_version
  FROM templates t
  JOIN template_versions v ON v.id = t.current_version_id
  WHERE t.key = 'madrasa' AND t.deleted_at IS NULL
    AND jsonb_typeof(v.config->'pages') = 'array'
), new_version AS (
  INSERT INTO template_versions (template_id, version, schema_version, config, changelog)
  SELECT cur.template_id,
    (SELECT max(v.version) + 1 FROM template_versions v WHERE v.template_id = cur.template_id),
