    'product page'
  FROM cur
  WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(cur.config->'pages') p WHERE p->>'kind' = 'product')
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(cur.config->'pages') p WHERE p->>'slug' = 'product')
  RETURNING id, template_id
)
UPDATE templates t SET current_version_id = nv.id, updated_at = now()
FROM new_version nv
WHERE t.id = nv.template_id;

-- Meta: the page's gallery name, never overwriting an existing value.
UPDATE templates t
SET meta = jsonb_set(t.meta, '{pageNames}', COALESCE(t.meta->'pageNames', '{}'::jsonb) || jsonb_build_object('product', '{"ar":"صفحة المنتج","en":"Product page"}'::jsonb))
WHERE t.key = 'garagy' AND t.deleted_at IS NULL
  AND t.meta->'pageNames'->'product' IS NULL;

-- mawsem
-- Lock the template row (as publishTemplateVersion does) before max(version) + 1.
SELECT 1 FROM templates WHERE key = 'mawsem' AND deleted_at IS NULL FOR UPDATE;

-- Draft: the page is appended to an admin draft that has none.
UPDATE templates t
