    draft_version = t.draft_version + 1,
    draft_updated_at = now()
WHERE t.key = 'tarik' AND t.deleted_at IS NULL
  AND t.draft_config IS NOT NULL AND jsonb_typeof(t.draft_config->'pages') = 'array'
  AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(t.draft_config->'pages') p WHERE p->>'kind' = 'product')
  AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(t.draft_config->'pages') p WHERE p->>'slug' = 'product');

-- Version: current config + the page, as version max + 1, made current.
WITH cur AS (
  SELECT t.id AS template_id, v.config, v.schema_version
  FROM templates t
  JOIN template_versions v ON v.id = t.current_version_id
  WHERE t.key = 'tarik' AND t.deleted_at IS NULL
    AND jsonb_typeof(v.config->'pages') = 'array'
), new_version AS (
  INSERT INTO template_versions (template_id, version, schema_version, config, changelog)
  SELECT cur.template_id,
    (SELECT max(v.version) + 1 FROM template_versions v WHERE v.template_id = cur.template_id),
    cur.schema_version,
    jsonb_set(cur.config, '{pages}', (cur.config->'pages') || '{"kind":"product","slug":"product","isHome":false,"name":"صفحة المنتج","showInNav":false,"seo":{},"content":{"sections":[{"id":"tarik-product-main","sectionId":"custom-section","version":1,"props":{},"componentTree":[{"id":"tarik-product-main-n1","type":"section","props":{"label":"المنتج","translations":{"en":{"label":"Product"}}},"children":[{"id":"tarik-product-main-n2","type":"container","props":{"label":"الحاوية","translations":{"en":{"label":"Container"}}},"children":[{"id":"tarik-product-main-n3","type":"textLink","props":{"label":"رابط الرجوع","text":"رجوع للعربية","href":"/","translations":{"en":{"label":"Back link","text":"Back to the car"}}},"children":[],"style":{"fontSize":"sm","color":"muted","marginBottom":20},"breakpointStyles":{"mobile":{"marginBottom":14}}},{"id":"tarik-product-main-n4","type":"grid","props":{"label":"المعرض والشراء","translations":{"en":{"label":"Gallery and buy column"}}},"children":[{"id":"tarik-product-main-n5","type":"productGallery","props":{"zoom":true,"label":"صور المنتج","thumbs":"side","translations":{"en":{"label":"Product gallery"}}},"children":[],"style":{"colSpan":7,"position":"sticky","insetTop":"96px"},"breakpointStyles":{"tablet":{"colSpan":1,"position":"relative","insetTop":"0px"}}},{"id":"tarik-product-main-n6","type":"vFlex","props":{"label":"عمود الشراء","translations":{"en":{"label":"Buy column"}}},"children":[{"id":"tarik-product-main-n7","type":"productSeller","props":{"label":"البائع","translations":{"en":{"label":"Seller"}}},"children":[]},{"id":"tarik-product-main-n8","type":"productStock","props":{"label":"المخزون","translations":{"en":{"label":"Stock"}}},"children":[]},{"id":"tarik-product-main-n9","type":"heading","props":{"role":"title","bind":"title","label":"اسم المنتج","text":"اسم المنتج","level":"h1","translations":{"en":{"label":"Product name","text":"Product name"}}},"children":[],"style":{"fontSize":"3xl","fontWeight":"bold","lineHei